namespace KotoNeko.Core.Domain;

/// <summary>Where a practice sentence came from.</summary>
public enum PracticeSentenceSource
{
    /// <summary>Promoted from the word's context sentence.</summary>
    Context = 0,

    /// <summary>Written by the user.</summary>
    Yours = 1,

    /// <summary>Generated by an LLM (Phase 2.5 step 5).</summary>
    Generated = 2,
}

/// <summary>Whether a practice sentence is in use.</summary>
public enum PracticeSentenceStatus
{
    /// <summary>Not used yet: waiting for the user's OK.</summary>
    Draft = 0,

    /// <summary>The user OK'd it, so it's in use.</summary>
    Approved = 1,

    /// <summary>A native speaker OK'd it; in use.</summary>
    NativeChecked = 2,

    /// <summary>Pulled from use until it's fixed.</summary>
    NeedsFix = 3,
}

/// <summary>
/// A sentence for practising one word by ear: in listening questions (the word,
/// then this sentence) and dictation. Unlike the context sentence, which is a
/// memory hook, a practice sentence is meant to be short and made only of words
/// the user knows, apart from the word itself; that is checked each time it's
/// used, so a sentence too hard today becomes usable as the user learns.
/// </summary>
public class PracticeSentence
{
    public const int MaxTextLength = 300;
    public const int MaxEnglishLength = 500;
    public const int MaxNoteLength = 500;

    public int Id { get; set; }

    public int VocabularyId { get; set; }
    public Vocabulary? Vocabulary { get; set; }

    public string Text { get; set; } = string.Empty;

    /// <summary>An English translation, shown after answering. May be empty.</summary>
    public string English { get; set; } = string.Empty;

    public PracticeSentenceSource Source { get; set; }

    public PracticeSentenceStatus Status { get; set; }

    public bool HasAudio { get; set; }

    /// <summary>The proofreader's note when they marked it "needs a fix".</summary>
    public string? ReviewNote { get; set; }

    /// <summary>When a proofreader last marked it OK or "needs a fix".</summary>
    public DateTime? ReviewedAt { get; set; }

    public DateTime CreatedAt { get; set; }

    public DateTime UpdatedAt { get; set; }

    /// <summary>The audio clip. Only loaded when asked for.</summary>
    public PracticeSentenceAudio? Audio { get; set; }

    /// <summary>Approved or native-checked: the sentence may be used.</summary>
    public bool InUse => Status is PracticeSentenceStatus.Approved or PracticeSentenceStatus.NativeChecked;
}

/// <summary>A practice sentence's audio, kept apart so listing sentences never loads it.</summary>
public class PracticeSentenceAudio
{
    public int Id { get; set; }

    public int PracticeSentenceId { get; set; }
    public PracticeSentence? PracticeSentence { get; set; }

    public byte[] Audio { get; set; } = Array.Empty<byte>();
}
